<?php
namespace App\Services;use Illuminate\Support\Facades\{DB,Schema,Storage};
class AcceptanceAuditService{public function run():array{$checks=[];$add=function($key,$passed,$detail)use(&$checks){$checks[]=['key'=>$key,'passed'=>(bool)$passed,'detail'=>$detail];};$tables=['institutions','floor_plans','surveys','measurements','heatmap_runs','ap_load_samples','feedback_responses','insights','comparison_runs','reports','audit_logs','validation_runs'];foreach($tables as$table)$add('table_'.$table,Schema::hasTable($table),$table);try{DB::select('select 1');$add('database_connection',true,'Database query succeeded.');}catch(\Throwable$e){$add('database_connection',false,$e->getMessage());}try{$disk=\App\Support\PersistentStorage::diskName();$path='acceptance/'.uniqid().'.txt';Storage::disk($disk)->put($path,'ok');$ok=Storage::disk($disk)->exists($path);Storage::disk($disk)->delete($path);$add('private_storage',$ok,'Private storage write/read/delete on '.$disk.'.');}catch(\Throwable$e){$add('private_storage',false,$e->getMessage());}$add('production_debug_disabled',app()->environment('production')?!config('app.debug'):true,app()->environment('production')?'APP_DEBUG must be false.':'Not evaluated as production.');$add('queue_configured',config('queue.default')!=='sync','Queue connection: '.config('queue.default'));$add('project_alignment',\App\Models\ProjectProfile::where('is_active',true)->whereHas('institution',fn($q)=>$q->where('name','Adekunle Ajasin University, Akungba'))->exists(),'AAUA active profile.');return['checks'=>$checks,'passed'=>collect($checks)->where('passed',true)->count(),'failed'=>collect($checks)->where('passed',false)->count(),'status'=>collect($checks)->every(fn($c)=>$c['passed'])?'passed':'attention_required'];}}
